import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'api.dart';
String iranStageLabel(int grade){if(grade<=3)return'دوره اول ابتدایی';if(grade<=6)return'دوره دوم ابتدایی';if(grade<=9)return'دوره اول متوسطه';return'دوره دوم متوسطه';}
int iranLocalYear(int grade){if(grade<=3)return grade;if(grade<=6)return grade-3;if(grade<=9)return grade-6;return grade-9;}
class IranianFamilyLearningHub extends StatefulWidget{const IranianFamilyLearningHub({super.key,required this.identity});final IdentityApi identity;@override State<IranianFamilyLearningHub> createState()=>_State();}
class _State extends State<IranianFamilyLearningHub>{int grade=7;String persona='child';String sex='unspecified';String birthDate='';late Future<List<Map<String,dynamic>>> data;String get baseUrl=>const String.fromEnvironment('LIFEMATE_API_URL',defaultValue:'http://localhost:8080');Future<Map<String,dynamic>> request(String method,String path,{Map<String,dynamic>? body})async{final req=http.Request(method,Uri.parse('$baseUrl$path'))..headers.addAll({'content-type':'application/json','authorization':'Bearer ${widget.identity.accessToken??''}'});if(body!=null){req.body=jsonEncode(body);}final res=await http.Response.fromStream(await req.send());if(res.statusCode<200||res.statusCode>=300){throw Exception('request_failed_${res.statusCode}');}return res.body.isEmpty?<String,dynamic>{}:jsonDecode(res.body)as Map<String,dynamic>;}@override void initState(){super.initState();data=load();}Future<List<Map<String,dynamic>>>load()async=>[await request('GET','/v1/me/iran-profile'),await request('GET','/v1/education/catalog?grade=$grade&schoolYear=1405-1406'),await request('GET','/v1/calendar/iran?year=1405'),await request('GET','/v1/me/notification-preferences'),await request('GET','/v1/me/menstrual-cycles')];void reload()=>setState(()=>data=load());Future<void>saveProfile()async{await request('PATCH','/v1/me/iran-profile',body:{'householdPersona':persona,'sex':sex,'birthDate':birthDate.isEmpty?null:birthDate});if(persona=='child'){await request('PUT','/v1/me/education',body:{'nationalGrade':grade,'schoolYear':'1405-1406'});}reload();}Future<void>pref(String key,bool value)async{await request('PATCH','/v1/me/notification-preferences',body:{key:value});reload();}Future<void>addCycle()async{final d=DateTime.now();final date='${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';await request('POST','/v1/me/menstrual-cycles',body:{'startsOn':date,'reminderEnabled':false});reload();}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('خانواده و یادگیری ایران')),body:FutureBuilder<List<Map<String,dynamic>>>(future:data,builder:(context,s){if(!s.hasData){return const Center(child:CircularProgressIndicator());}final prefs=s.data![3];final catalog=s.data![1]['subjects']as List<dynamic>? ?? const [];final events=s.data![2]['events']as List<dynamic>? ?? const [];final cycles=s.data![4]['entries']as List<dynamic>? ?? const [];return ListView(padding:const EdgeInsets.all(16),children:[Text('پروفایل ایرانی',style:Theme.of(context).textTheme.titleLarge),DropdownButtonFormField<String>(initialValue:persona,decoration:const InputDecoration(labelText:'نقش'),items:const[DropdownMenuItem(value:'mother',child:Text('مادر')),DropdownMenuItem(value:'father',child:Text('پدر')),DropdownMenuItem(value:'child',child:Text('فرزند')),DropdownMenuItem(value:'adult',child:Text('بزرگسال'))],onChanged:(v)=>setState(()=>persona=v??persona)),DropdownButtonFormField<String>(initialValue:sex,decoration:const InputDecoration(labelText:'جنسیت'),items:const[DropdownMenuItem(value:'female',child:Text('دختر / زن')),DropdownMenuItem(value:'male',child:Text('پسر / مرد')),DropdownMenuItem(value:'unspecified',child:Text('ذکر نشود'))],onChanged:(v)=>setState(()=>sex=v??sex)),TextFormField(initialValue:birthDate,decoration:const InputDecoration(labelText:'تاریخ تولد (YYYY-MM-DD)'),onChanged:(v)=>birthDate=v),if(persona=='child')DropdownButtonFormField<int>(initialValue:grade,decoration:const InputDecoration(labelText:'پایه تحصیلی'),items:[for(var g=1;g<=12;g++)DropdownMenuItem(value:g,child:Text('پایه $g — ${iranStageLabel(g)}، سال ${iranLocalYear(g)}'))],onChanged:(v)=>setState(()=>grade=v??grade)),FilledButton(onPressed:saveProfile,child:const Text('ذخیره پروفایل')),const Divider(),Text('کتاب‌ها و درس‌ها',style:Theme.of(context).textTheme.titleLarge),const Text('منبع رسمی کتاب‌ها لینک می‌شود؛ PDF بدون مجوز بازتوزیع بسته‌بندی نمی‌شود.'),...catalog.map((raw){final r=Map<String,dynamic>.from(raw as Map);return ListTile(leading:const Icon(Icons.menu_book_outlined),title:Text(r['name_fa']?.toString()??''),subtitle:Text(r['source_url']?.toString()??''));}),const Divider(),Text('تقویم جلالی ۱۴۰۵',style:Theme.of(context).textTheme.titleLarge),const Text('هفته از شنبه آغاز می‌شود؛ پنج‌شنبه و جمعه آخرهفته پیش‌فرض‌اند.'),...events.take(40).map((raw){final r=Map<String,dynamic>.from(raw as Map);return ListTile(leading:Icon(r['is_official_holiday']==true?Icons.event_busy_outlined:Icons.event_outlined),title:Text(r['title_fa']?.toString()??''),subtitle:Text('${r['jalali_month']}/${r['jalali_day']}'));}),const Divider(),Text('یادآوری و اعلان',style:Theme.of(context).textTheme.titleLarge),SwitchListTile(title:const Text('بنر داخل برنامه'),value:prefs['in_app_banner']==true,onChanged:(v)=>pref('inAppBanner',v)),SwitchListTile(title:const Text('یادآوری مدرسه'),value:prefs['school_reminders']!=false,onChanged:(v)=>pref('schoolReminders',v)),SwitchListTile(title:const Text('یادآوری تقویم'),value:prefs['calendar_reminders']!=false,onChanged:(v)=>pref('calendarReminders',v)),SwitchListTile(title:const Text('نمایش متن حساس روی اعلان'),value:prefs['sensitive_preview']==true,onChanged:(v)=>pref('sensitivePreview',v)),const Divider(),Text('چرخه شخصی',style:Theme.of(context).textTheme.titleLarge),const Text('فقط برای صاحب حساب؛ ابزار ثبت و یادآوری است و کاربرد تشخیصی ندارد.'),FilledButton.icon(onPressed:addCycle,icon:const Icon(Icons.add),label:const Text('ثبت شروع امروز')),Text('${cycles.length} ثبت خصوصی')]);}));}
